function bindNotifications(){document.querySelectorAll('[data-notification]').forEach(button=>button.onclick=()=>openNotification(button.dataset.notification));const read=document.querySelector('#read-notifications');if(read)read.onclick=async()=>{const{error}=await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('user_id',state.session.user.id).is('read_at',null);if(error){state.error=error.message;render()}else await loadData()}}
async function loadData(){
  if(!supabase||!state.session)return;
  state.busy=true;render();
  const[tx,inv,reconciliations,cat,budgets,accounts,bankConnections,emailAccounts,emails,attachments,notifications,profile]=await Promise.all([
    supabase.from('transactions').select('*,categories!transactions_category_id_fkey(name)').order('occurred_on',{ascending:false}),
    supabase.from('invoices').select('*,categories!invoices_category_id_fkey(name)').order('due_on',{ascending:true}),
    supabase.from('reconciliations').select('*').eq('status','suggested').order('created_at',{ascending:false}),
    supabase.from('categories').select('*').order('name'),
    supabase.from('budgets').select('*').order('created_at'),
    supabase.from('accounts').select('*').order('created_at'),
    supabase.from('bank_connections').select('*').order('created_at'),
    supabase.from('email_accounts').select('*').eq('user_id',state.session.user.id).order('created_at'),
    supabase.from('emails').select('*').eq('user_id',state.session.user.id).not('financial_status','is',null).order('received_at',{ascending:false}).limit(100),
    supabase.from('attachments').select('*').eq('user_id',state.session.user.id).not('email_id','is',null).order('created_at'),
    supabase.from('notifications').select('*').eq('user_id',state.session.user.id).is('read_at',null).order('created_at',{ascending:false}).limit(20),
    supabase.from('profiles').select('transactions_start_on,timezone').eq('id',state.session.user.id).maybeSingle()]);
  const failed=[tx,inv,reconciliations,cat,budgets,accounts,bankConnections,emailAccounts,emails,attachments,notifications,profile].find(x=>x.error)?.error;
  if(failed)state.error=failed.message;else{state.transactions=tx.data;state.invoices=inv.data;state.reconciliations=reconciliations.data;state.categories=cat.data;state.budgets=budgets.data;state.accounts=accounts.data;state.bankConnections=bankConnections.data;state.emailAccounts=emailAccounts.data;state.emails=emails.data;state.attachments=attachments.data;state.notifications=notifications.data;state.profile=profile.data}
  state.busy=false;render();
  if(state.emailAccounts.length&&!state.autoSyncStarted){state.autoSyncStarted=true;setTimeout(()=>{enablePush(false);syncRecentEmails(null,true)},500)}
  if(state.accounts.some(account=>account.external_provider==='enablebanking')&&!state.bankSyncStarted){state.bankSyncStarted=true;setTimeout(()=>syncBanks(true),900)}
}

function authView(){
  app.innerHTML=`<main class="auth-shell"><section class="auth-card"><div class="brand large"><span>${ico('WalletCards')}</span>SOLDI</div><p class="kicker">IL TUO SPAZIO FINANZIARIO</p><h1>Tutto sotto controllo.</h1><p class="auth-copy">Accedi per gestire entrate, spese, fatture e scadenze in uno spazio personale protetto.</p>${!cloudReady?'<div class="alert warning">Configurazione cloud non completata. Aggiungi le variabili Supabase al progetto Vercel.</div>':''}${state.error?`<div class="alert">${safeText(state.error)}</div>`:''}<form id="auth-form"><label>Email<input type="email" name="email" autocomplete="email" value="${safeText(state.authEmail)}" required></label><label>Password<input type="password" name="password" autocomplete="current-password" minlength="8" required></label><button class="primary wide" ${!cloudReady?'disabled':''}>Accedi con account esistente</button><button class="secondary wide" type="button" id="signup" ${!cloudReady?'disabled':''}>Prima volta? Crea account</button></form><p class="legal">I dati sono separati per utente tramite policy di sicurezza del database.</p></section></main>`;
  draw();if(!cloudReady)return;
  const form=document.querySelector('#auth-form');
  form.onsubmit=e=>authenticate(e,false);
  document.querySelector('#signup').onclick=()=>{if(form.reportValidity())authenticate({preventDefault(){},currentTarget:form},true)};
}
async function authenticate(event,signup){
  event.preventDefault();state.error='';const form=event.currentTarget;
  if(!form.reportValidity())return;
  const credentials=authCredentials(Object.fromEntries(new FormData(form)));
  if(credentials.error){state.error=credentials.error;authView();return}
  const{email,password}=credentials;
  state.authEmail=email;
  const result=signup?await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin}}):await supabase.auth.signInWithPassword({email,password});
  if(result.error){state.error=authErrorMessage(result.error.message);authView()}else if(signup&&!result.data.session){state.error='Account creato. Controlla la tua email per confermare l’accesso.';authView()}
}

function shell(content,view=''){
  const user=state.session.user;
  const linkedEmailIds=new Set(state.invoices.map(invoice=>invoice.source_email_id).filter(Boolean)),deadlineCount=state.invoices.filter(invoice=>invoice.status==='to_pay').length+state.emails.filter(message=>message.financial_status==='to_pay'&&!linkedEmailIds.has(message.id)).length,bellCount=state.notifications.length||deadlineCount;
  app.innerHTML=`<div class="app-shell ${view}"><aside class="sidebar"><div class="brand"><span>${ico('WalletCards')}</span>SOLDI</div><nav>${pages.map(([label,glyph])=>`<button data-page="${label}" class="${state.page===label?'active':''}">${ico(glyph)}<span>${label}</span></button>`).join('')}</nav><div class="account"><div class="avatar">${safeText(user.email[0].toUpperCase())}</div><div><strong>${safeText(user.email.split('@')[0])}</strong><small>${safeText(user.email)}</small></div><button id="logout" title="Esci">${ico('LogOut')}</button></div></aside><main class="workspace"><header><button class="menu" id="menu">${ico('Menu')}</button><div><p class="kicker">GESTIONE FINANZIARIA</p><h1>${state.page}</h1></div><button class="notification-bell ${deadlineCount?'has-deadlines':''}" id="notification-bell" aria-label="${deadlineCount?`${deadlineCount} scadenze aperte`:`${state.notifications.length} notifiche non lette`}">${ico('Bell')}${bellCount?`<b>${bellCount}</b>`:''}</button><div class="cloud-state">${ico('Cloud')}<span>Cloud attivo</span></div></header>${state.notice?`<div class="alert success">${safeText(state.notice)}</div>`:''}${state.error?`<div class="alert">${safeText(state.error)}</div>`:''}${state.busy?'<div class="loader">Sincronizzazione…</div>':''}<section>${content}</section></main><button class="scrim" id="scrim" aria-label="Chiudi menu"></button></div>`;
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));
  document.querySelector('#menu').onclick=()=>document.querySelector('.app-shell').classList.add('menu-open');
  document.querySelector('#scrim').onclick=()=>document.querySelector('.app-shell').classList.remove('menu-open');
  document.querySelector('#notification-bell').onclick=()=>setPage(deadlineCount?'Scadenze':'Home');
  document.querySelector('#logout').onclick=()=>supabase.auth.signOut();draw();
}
