function settingsPage(){
  const startOn=state.profile?.transactions_start_on||'2026-09-19',notificationGranted=pushAvailable()&&Notification.permission==='granted',pushState=!pushAvailable()?'Non disponibile in questo browser':notificationGranted?'Attive':'Da attivare',bankAccounts=bankBalanceSummary(state.accounts).accounts.length,installed=appInstalled();
  shell(`<div class="settings-grid"><article class="panel setting-card"><div class="row-icon">${ico('UserRound')}</div><div><p class="kicker">ACCOUNT SOLDI</p><h2>${safeText(state.session.user.email)}</h2><small>I tuoi dati sono separati e protetti per questo account.</small></div></article><article class="panel setting-card"><div class="row-icon">${ico('Smartphone')}</div><div><p class="kicker">APP TELEFONO</p><h2>${installed?'Installata':'Pronta da installare'}</h2><small>Si apre a schermo intero con la sua icona, usando gli stessi dati protetti del sito.</small><button class="secondary" id="install-app" ${installed?'disabled':''}>${ico(installed?'BadgeCheck':'Download')} ${installed?'App installata':'Installa sul telefono'}</button></div></article><article class="panel setting-card"><div class="row-icon">${ico('Bell')}</div><div><p class="kicker">NOTIFICHE</p><h2>${pushState}</h2><small>Avvisi per fatture, scadenze e pagamenti da controllare.</small><button class="secondary" id="settings-push" ${!pushAvailable()?'disabled':''}>${ico('BellRing')} ${notificationGranted?'Verifica notifiche':'Attiva notifiche'}</button></div></article><article class="panel setting-card"><div class="row-icon">${ico('Mail')}</div><div><p class="kicker">GMAIL</p><h2>${state.emailAccounts.length} account collegat${state.emailAccounts.length===1?'o':'i'}</h2><small>Controllo dal giorno 1 del mese e ogni giorno alle 17:00.</small><button class="secondary" data-settings-page="Email">Gestisci Gmail</button></div></article><article class="panel setting-card"><div class="row-icon">${ico('Landmark')}</div><div><p class="kicker">CONTI BANCARI</p><h2>${bankAccounts} IBAN collegat${bankAccounts===1?'o':'i'}</h2><small>Movimenti sincronizzati e duplicati esclusi.</small><button class="secondary" data-settings-page="Banca">Gestisci banche</button></div></article><article class="panel setting-card"><div class="row-icon">${ico('CalendarRange')}</div><div><p class="kicker">INIZIO REGISTRAZIONE</p><h2>${date(startOn)}</h2><small>SOLDI registra i movimenti da questa data fino a oggi. Le date future vengono rifiutate.</small></div></article><article class="panel setting-card"><div class="row-icon">${ico('Clock3')}</div><div><p class="kicker">ORA ITALIANA</p><h2>Europe/Rome</h2><small>Il controllo automatico viene eseguito alle 17:00, anche con il cambio dell’ora.</small></div></article><article class="panel setting-card"><div class="row-icon">${ico('DatabaseBackup')}</div><div><p class="kicker">COPIA PERSONALE</p><h2>Backup dei dati</h2><small>Scarica una copia di movimenti, fatture, categorie e budget.</small><button class="secondary" data-settings-page="Backup">Apri backup</button></div></article></div>`);
  document.querySelectorAll('[data-settings-page]').forEach(button=>button.onclick=()=>setPage(button.dataset.settingsPage));
  const install=document.querySelector('#install-app');if(install)install.onclick=installPhoneApp;
  const push=document.querySelector('#settings-push');if(push)push.onclick=async()=>{try{push.disabled=true;const active=await enablePush(true);if(!active){state.notice='Consenti le notifiche nelle impostazioni del browser.';render();return}const{data,error}=await supabase.functions.invoke('push-test');if(error||!data?.sent)throw new Error(await functionError(error,data?.error||'Notifica di prova non inviata.'));state.notice='Notifica di prova inviata al telefono.';render()}catch(error){state.error=error.message;render()}};draw();
}
function placeholder(title,copy,glyph){shell(`<article class="panel placeholder"><div class="placeholder-icon">${ico(glyph)}</div><p class="kicker">MODULO PREPARATO</p><h2>${title}</h2><p>${copy}</p></article>`);draw()}
function backupPage(){shell(`<article class="panel backup-card"><div class="placeholder-icon">${ico('DatabaseBackup')}</div><p class="kicker">COPIA PERSONALE</p><h2>Backup dei tuoi dati SOLDI</h2><p>Scarica movimenti, fatture, scadenze, categorie e budget in un unico file JSON. Password, credenziali bancarie, token Gmail e notifiche del telefono non vengono esportati.</p><button class="primary" id="download-backup">${ico('Download')} Scarica backup</button><small>I PDF e le foto restano protetti nello spazio documenti e non sono inclusi nel file.</small></article>`);const button=document.querySelector('#download-backup');button.onclick=async()=>{button.disabled=true;button.textContent='Preparazione backup…';const{data,error}=await supabase.functions.invoke('data-export');if(error||!data?.data){state.error=await functionError(error,data?.error||'Impossibile creare il backup.');render();return}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`SOLDI-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);state.notice='Backup scaricato sul dispositivo.';render()};draw()}
function render(){if(!state.session)return authView();const routes={Home:home,Fatture:invoicesPage,Entrate:()=>transactionPage('income'),Spese:()=>transactionPage('expense'),'Da classificare':classificationPage,Riepilogo:summaryPage,Scadenze:deadlinesPage,Statistiche:statsPage,Email:emailPage,Banca:bankPage,Backup:backupPage,Impostazioni:settingsPage};(routes[state.page]||home)()}

const callback=new URLSearchParams(location.search),requestedPage=callback.get('page');if(pages.some(([label])=>label===requestedPage))state.page=requestedPage;if(callback.has('gmail')){state.page='Email';if(callback.get('gmail')==='connected')state.notice='Account Gmail collegato correttamente.';else state.error=callback.get('detail')||'Collegamento Gmail non riuscito.';history.replaceState({},'',location.pathname)}if(callback.has('bank')){state.page='Banca';if(callback.get('bank')==='connected')state.notice='Banca collegata correttamente.';else state.error=callback.get('detail')||'Collegamento bancario non riuscito.';history.replaceState({},'',location.pathname)}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
checkAppVersion();document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkAppVersion()});setInterval(checkAppVersion,300000);
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();state.deferredInstallPrompt=event;if(state.session&&state.page==='Impostazioni')render()});
window.addEventListener('appinstalled',()=>{state.deferredInstallPrompt=null;state.notice='SOLDI installata sul telefono.';if(state.session)render()});
if(supabase){supabase.auth.getSession().then(({data})=>{state.session=data.session;if(state.session)loadData();else render()});supabase.auth.onAuthStateChange((event,session)=>{state.session=session;if(event==='SIGNED_IN')setTimeout(loadData,0);else{state.autoSyncStarted=false;state.bankSyncStarted=false;render()}})}else render();
